7	import type { AgentCard, Message, MessageSendParams, Task } from '@a2a-js/sdk';
8	import {
9	  type Client,
10	  ClientFactory,
11	  ClientFactoryOptions,
12	  DefaultAgentCardResolver,
13	  RestTransportFactory,
14	  JsonRpcTransportFactory,
15	  type AuthenticationHandler,
16	  createAuthenticatingFetchWithRetry,
17	} from '@a2a-js/sdk/client';
18	import { v4 as uuidv4 } from 'uuid';
19	import { debugLogger } from '../utils/debugLogger.js';
20	
21	export type SendMessageResult = Message | Task;
22	
23	/**
24	 * Manages A2A clients and caches loaded agent information.
25	 * Follows a singleton pattern to ensure a single client instance.
26	 */
27	export class A2AClientManager {
28	  private static instance: A2AClientManager;
29	
30	  // Each agent should manage their own context/taskIds/card/etc
31	  private clients = new Map<string, Client>();
32	  private agentCards = new Map<string, AgentCard>();
33	
34	  private constructor() {}
35	
36	  /**
37	   * Gets the singleton instance of the A2AClientManager.
38	   */
39	  static getInstance(): A2AClientManager {
40	    if (!A2AClientManager.instance) {
41	      A2AClientManager.instance = new A2AClientManager();
42	    }
43	    return A2AClientManager.instance;
44	  }
45	
46	  /**
47	   * Resets the singleton instance. Only for testing purposes.
48	   * @internal
49	   */
50	  static resetInstanceForTesting() {
51	    // @ts-expect-error - Resetting singleton for testing
52	    A2AClientManager.instance = undefined;
53	  }
54	
55	  /**
56	   * Loads an agent by fetching its AgentCard and caches the client.
57	   * @param name The name to assign to the agent.
58	   * @param agentCardUrl The full URL to the agent's card.
59	   * @param authHandler Optional authentication handler to use for this agent.
60	   * @returns The loaded AgentCard.
61	   */
62	  async loadAgent(
63	    name: string,
64	    agentCardUrl: string,
65	    authHandler?: AuthenticationHandler,
66	  ): Promise<AgentCard> {
67	    if (this.clients.has(name) && this.agentCards.has(name)) {
68	      throw new Error(`Agent with name '${name}' is already loaded.`);
69	    }
70	
71	    let fetchImpl: typeof fetch = fetch;
72	    if (authHandler) {
73	      fetchImpl = createAuthenticatingFetchWithRetry(fetch, authHandler);
74	    }
75	
76	    const resolver = new DefaultAgentCardResolver({ fetchImpl });
77	
78	    const options = ClientFactoryOptions.createFrom(
79	      ClientFactoryOptions.default,
80	      {
81	        transports: [
82	          new RestTransportFactory({ fetchImpl }),
83	          new JsonRpcTransportFactory({ fetchImpl }),
84	        ],
85	        cardResolver: resolver,
86	      },
87	    );
88	
89	    const factory = new ClientFactory(options);
90	    const client = await factory.createFromUrl(agentCardUrl, '');
91	    const agentCard = await client.getAgentCard();
92	
93	    this.clients.set(name, client);
94	    this.agentCards.set(name, agentCard);
95	
96	    debugLogger.debug(
97	      `[A2AClientManager] Loaded agent '${name}' from ${agentCardUrl}`,
98	    );
99	
100	    return agentCard;
101	  }
102	
103	  /**
104	   * Invalidates all cached clients and agent cards.
105	   */
106	  clearCache(): void {
107	    this.clients.clear();
108	    this.agentCards.clear();
109	    debugLogger.debug('[A2AClientManager] Cache cleared.');
110	  }
111	
112	  /**
113	   * Sends a message to a loaded agent.
114	   * @param agentName The name of the agent to send the message to.
115	   * @param message The message content.
116	   * @param options Optional context and task IDs to maintain conversation state.
117	   * @returns The response from the agent (Message or Task).
118	   * @throws Error if the agent returns an error response.
119	   */
120	  async sendMessage(
121	    agentName: string,
122	    message: string,
123	    options?: { contextId?: string; taskId?: string },
124	  ): Promise<SendMessageResult> {
125	    const client = this.clients.get(agentName);
126	    if (!client) {
127	      throw new Error(`Agent '${agentName}' not found.`);
128	    }
129	
130	    const messageParams: MessageSendParams = {
131	      message: {
132	        kind: 'message',
133	        role: 'user',
134	        messageId: uuidv4(),
135	        parts: [{ kind: 'text', text: message }],
136	        contextId: options?.contextId,
137	        taskId: options?.taskId,
138	      },
139	      configuration: {
140	        blocking: true,
141	      },
142	    };
143	
144	    try {
145	      return await client.sendMessage(messageParams);
146	    } catch (error: unknown) {
147	      const prefix = `A2AClient SendMessage Error [${agentName}]`;
148	      if (error instanceof Error) {
149	        throw new Error(`${prefix}: ${error.message}`, { cause: error });
150	      }
151	      throw new Error(
152	        `${prefix}: Unexpected error during sendMessage: ${String(error)}`,
153	      );
154	    }
155	  }
156	
157	  /**
158	   * Retrieves a loaded agent card.
159	   * @param name The name of the agent.
160	   * @returns The agent card, or undefined if not found.
161	   */
162	  getAgentCard(name: string): AgentCard | undefined {
163	    return this.agentCards.get(name);
164	  }
165	
166	  /**
167	   * Retrieves a loaded client.
168	   * @param name The name of the agent.
169	   * @returns The client, or undefined if not found.
170	   */
171	  getClient(name: string): Client | undefined {
172	    return this.clients.get(name);
173	  }
174	
175	  /**
176	   * Retrieves a task from an agent.
177	   * @param agentName The name of the agent.
178	   * @param taskId The ID of the task to retrieve.
179	   * @returns The task details.
180	   */
181	  async getTask(agentName: string, taskId: string): Promise<Task> {
182	    const client = this.clients.get(agentName);
183	    if (!client) {
184	      throw new Error(`Agent '${agentName}' not found.`);
185	    }
186	    try {
187	      return await client.getTask({ id: taskId });
188	    } catch (error: unknown) {
189	      const prefix = `A2AClient getTask Error [${agentName}]`;
190	      if (error instanceof Error) {
191	        throw new Error(`${prefix}: ${error.message}`, { cause: error });
192	      }
193	      throw new Error(`${prefix}: Unexpected error: ${String(error)}`);
194	    }
195	  }
196	
197	  /**
198	   * Cancels a task on an agent.
199	   * @param agentName The name of the agent.
200	   * @param taskId The ID of the task to cancel.
201	   * @returns The cancellation response.
202	   */
203	  async cancelTask(agentName: string, taskId: string): Promise<Task> {
204	    const client = this.clients.get(agentName);
205	    if (!client) {
206	      throw new Error(`Agent '${agentName}' not found.`);
207	    }
208	    try {
209	      return await client.cancelTask({ id: taskId });
210	    } catch (error: unknown) {
211	      const prefix = `A2AClient cancelTask Error [${agentName}]`;
212	      if (error instanceof Error) {
213	        throw new Error(`${prefix}: ${error.message}`, { cause: error });
214	      }
215	      throw new Error(`${prefix}: Unexpected error: ${String(error)}`);
216	    }
217	  }
218	}
