7	import type {
8	  ToolConfirmationOutcome,
9	  ToolResult,
10	  ToolCallConfirmationDetails,
11	} from '../tools/tools.js';
12	import { BaseToolInvocation } from '../tools/tools.js';
13	import { DEFAULT_QUERY_STRING } from './types.js';
14	import type {
15	  RemoteAgentInputs,
16	  RemoteAgentDefinition,
17	  AgentInputs,
18	} from './types.js';
19	import type { MessageBus } from '../confirmation-bus/message-bus.js';
20	import { A2AClientManager } from './a2a-client-manager.js';
21	import {
22	  extractMessageText,
23	  extractTaskText,
24	  extractIdsFromResponse,
25	} from './a2aUtils.js';
26	import { GoogleAuth } from 'google-auth-library';
27	import type { AuthenticationHandler } from '@a2a-js/sdk/client';
28	import { debugLogger } from '../utils/debugLogger.js';
29	
30	/**
31	 * Authentication handler implementation using Google Application Default Credentials (ADC).
32	 */
33	export class ADCHandler implements AuthenticationHandler {
34	  private auth = new GoogleAuth({
35	    scopes: ['https://www.googleapis.com/auth/cloud-platform'],
36	  });
37	
38	  async headers(): Promise<Record<string, string>> {
39	    try {
40	      const client = await this.auth.getClient();
41	      const token = await client.getAccessToken();
42	      if (token.token) {
43	        return { Authorization: `Bearer ${token.token}` };
44	      }
45	      throw new Error('Failed to retrieve ADC access token.');
46	    } catch (e) {
47	      const errorMessage = `Failed to get ADC token: ${
48	        e instanceof Error ? e.message : String(e)
49	      }`;
50	      debugLogger.log('ERROR', errorMessage);
51	      throw new Error(errorMessage);
52	    }
53	  }
54	
55	  async shouldRetryWithHeaders(
56	    _response: unknown,
57	  ): Promise<Record<string, string> | undefined> {
58	    // For ADC, we usually just re-fetch the token if needed.
59	    return this.headers();
60	  }
61	}
62	
63	/**
64	 * A tool invocation that proxies to a remote A2A agent.
65	 *
66	 * This implementation bypasses the local `LocalAgentExecutor` loop and directly
67	 * invokes the configured A2A tool.
68	 */
69	export class RemoteAgentInvocation extends BaseToolInvocation<
70	  RemoteAgentInputs,
71	  ToolResult
72	> {
73	  // Persist state across ephemeral invocation instances.
74	  private static readonly sessionState = new Map<
75	    string,
76	    { contextId?: string; taskId?: string }
77	  >();
78	  // State for the ongoing conversation with the remote agent
79	  private contextId: string | undefined;
80	  private taskId: string | undefined;
81	  // TODO: See if we can reuse the singleton from AppContainer or similar, but for now use getInstance directly
82	  // as per the current pattern in the codebase.
83	  private readonly clientManager = A2AClientManager.getInstance();
84	  private readonly authHandler = new ADCHandler();
85	
86	  constructor(
87	    private readonly definition: RemoteAgentDefinition,
88	    params: AgentInputs,
89	    messageBus: MessageBus,
90	    _toolName?: string,
91	    _toolDisplayName?: string,
92	  ) {
93	    const query = params['query'] ?? DEFAULT_QUERY_STRING;
94	    if (typeof query !== 'string') {
95	      throw new Error(
96	        `Remote agent '${definition.name}' requires a string 'query' input.`,
97	      );
98	    }
99	    // Safe to pass strict object to super
100	    super(
101	      { query },
102	      messageBus,
103	      _toolName ?? definition.name,
104	      _toolDisplayName ?? definition.displayName,
105	    );
106	  }
107	
108	  getDescription(): string {
109	    return `Calling remote agent ${this.definition.displayName ?? this.definition.name}`;
110	  }
111	
112	  protected override async getConfirmationDetails(
113	    _abortSignal: AbortSignal,
114	  ): Promise<ToolCallConfirmationDetails | false> {
115	    // For now, always require confirmation for remote agents until we have a policy system for them.
116	    return {
117	      type: 'info',
118	      title: `Call Remote Agent: ${this.definition.displayName ?? this.definition.name}`,
119	      prompt: `Calling remote agent: "${this.params.query}"`,
120	      onConfirm: async (_outcome: ToolConfirmationOutcome) => {
121	        // Policy updates are now handled centrally by the scheduler
122	      },
123	    };
124	  }
125	
126	  async execute(_signal: AbortSignal): Promise<ToolResult> {
127	    // 1. Ensure the agent is loaded (cached by manager)
128	    // We assume the user has provided an access token via some mechanism (TODO),
129	    // or we rely on ADC.
130	    try {
131	      const priorState = RemoteAgentInvocation.sessionState.get(
132	        this.definition.name,
133	      );
134	      if (priorState) {
135	        this.contextId = priorState.contextId;
136	        this.taskId = priorState.taskId;
137	      }
138	
139	      if (!this.clientManager.getClient(this.definition.name)) {
140	        await this.clientManager.loadAgent(
141	          this.definition.name,
142	          this.definition.agentCardUrl,
143	          this.authHandler,
144	        );
145	      }
146	
147	      const message = this.params.query;
148	
149	      const response = await this.clientManager.sendMessage(
150	        this.definition.name,
151	        message,
152	        {
153	          contextId: this.contextId,
154	          taskId: this.taskId,
155	        },
156	      );
157	
158	      // Extracts IDs, taskID will be undefined if the task is completed/failed/canceled.
159	      const { contextId, taskId } = extractIdsFromResponse(response);
160	
161	      this.contextId = contextId ?? this.contextId;
162	      this.taskId = taskId;
163	
164	      RemoteAgentInvocation.sessionState.set(this.definition.name, {
165	        contextId: this.contextId,
166	        taskId: this.taskId,
167	      });
168	
169	      // Extract the output text
170	      const outputText =
171	        response.kind === 'task'
172	          ? extractTaskText(response)
173	          : response.kind === 'message'
174	            ? extractMessageText(response)
175	            : JSON.stringify(response);
176	
177	      debugLogger.debug(
178	        `[RemoteAgent] Response from ${this.definition.name}:\n${JSON.stringify(response, null, 2)}`,
179	      );
180	
181	      return {
182	        llmContent: [{ text: outputText }],
183	        returnDisplay: outputText,
184	      };
185	    } catch (error: unknown) {
186	      const errorMessage = `Error calling remote agent: ${error instanceof Error ? error.message : String(error)}`;
187	      return {
188	        llmContent: [{ text: errorMessage }],
189	        returnDisplay: errorMessage,
190	        error: { message: errorMessage },
191	      };
192	    }
193	  }
