 * it suitable for streaming partial output to the user.
 */
export class A2AResultReassembler {
  /** Ordered message sections gathered from messages and status updates. */
  private readonly messages: string[] = [];
  /** Reassembled artifact text keyed by artifactId. */
  private readonly artifacts = new Map<
    string,
    { name?: string; text: string }
  >();
  /** Preserves the order in which artifacts were first seen. */
  private readonly artifactOrder: string[] = [];

