   * Processes a single streaming event, updating the internal reassembled state.
   */
  update(result: SendMessageResult): void {
    switch (result.kind) {
      case 'message':
        this.pushMessage(result);
        break;
      case 'status-update':
        this.handleStatusUpdate(result);
        break;
      case 'artifact-update':
        this.handleArtifactUpdate(result);
        break;
      case 'task':
        this.pushMessage(result.status?.message);
        if (result.artifacts) {
          for (const artifact of result.artifacts) {
            this.upsertArtifact(artifact, false);
